  {
    id: "sindou-historical-forges-history-v2",
    type: "historical",
    parent: "BF-02",
    coords: [-5.15, 10.6667],
    name: { de: "Historische Schmieden von Sindou", hu: "Sindou történelmi kovácsműhelyei", ro: "Fierăriile istorice din Sindou", en: "Sindou Historical Forges"},
    image: "/poi-images/sindou-historical-forges-history-v2.webp",
    description: { de: "Alte Stätten der Eisenverarbeitung, die für lokale Werkzeuge und Waffen entscheidend waren.", hu: "Régi vasfeldolgozó helyek, amelyek kulcsfontosságúak voltak a helyi szerszámok és fegyverek szempontjából.", ro: "Vechi situri de prelucrare a fierului cruciale pentru uneltele și armele locale.", en: "Old iron processing sites crucial for local tools and weapons." },
    facts: {
      de: ["Zeigen das frühe metallurgische Wissen der Region.", "Wurden von Generation zu Generation weitergegeben."],
      hu: ["A régió korai kohászati tudását mutatják be.", "Generációról generációra örökítették."],
      ro: ["Arată cunoștințele metalurgice timpurii ale regiunii.", "Au fost transmise din generație în generație."],
      en: ["Show the early metallurgical knowledge of the region.", "Were passed down from generation to generation."]
    },
    descriptionAdvanced: {
      de: "Die historischen Schmieden von Sindou in Burkina Faso sind Überreste einer alten Eisenverarbeitungstradition. Sie befinden sich in der Stadt Sindou in der Region Cascades. Die Schmieden stammen aus dem 15. Jahrhundert und wurden von den Senufo-Völkern betrieben. Die Anlagen umfassen Schmelzöfen, Hämmer und Ambosse aus Stein. Das Eisen wurde aus lokalen Erzen gewonnen. Die Schmieden waren ein wichtiges wirtschaftliches Zentrum der Region. Heute sind sie ein geschütztes Kulturerbe und eine Touristenattraktion.",
      hu: "A sindou-i történelmi kovácsműhelyek Burkina Fasóban egy régi vasfeldolgozási hagyomány maradványai. Sindou városában, a Cascades régióban találhatók. A kovácsműhelyek a 15. századból származnak, és a szenufo népek üzemeltették őket. A létesítmények olvasztókemencéket, kalapácsokat és kőüllőket foglalnak magukban. A vasat helyi ércekből nyerték. A kovácsműhelyek a régió fontos gazdasági központjai voltak. Ma védett kulturális örökség és turisztikai látványosság.",
      ro: "Forjele istorice din Sindou, Burkina Faso, sunt rămășițe ale unei vechi tradiții de prelucrare a fierului. Situate în orașul Sindou, regiunea Cascades, forjele datează din secolul al XV-lea și au fost operate de poporul Senufo. Instalațiile includ cuptoare de topire, ciocane și nicovale de piatră. Fierul era obținut din minereuri locale. Forjele au fost un important centru economic al regiunii. Astăzi sunt un patrimoniu cultural protejat și o atracție turistică.",
      en: "The historical forges of Sindou in Burkina Faso are remnants of an ancient ironworking tradition. Located in Sindou town, Cascades region, the forges date back to the 15th century and were operated by the Senufo people. The site includes smelting furnaces, hammers, and stone anvils. Iron was extracted from local ores. The forges were a vital economic center. Today, they are a protected cultural heritage site and a tourist attraction.",
    },
    factsAdvanced: {
      de: ["Zeitraum: 15. Jahrhundert.", "Standort: Sindou, Region Cascades, Burkina Faso.", "Betreiber: Senufo-Volk.", "Anzahl der erhaltenen Öfen: 3.", "Verwendetes Erz: lateritisches Eisenerz.", "Schutzstatus: Kulturdenkmal seit 2005."],
      hu: ["Időszak: 15. század.", "Helyszín: Sindou, Cascades régió, Burkina Faso.", "Üzemeltető: szenufo nép.", "Fennmaradt kemencék száma: 3.", "Felhasznált érc: laterit vasérc.", "Védettség: kulturális emlék 2005 óta."],
      ro: ["Perioada: secolul al XV-lea.", "Locație: Sindou, regiunea Cascades, Burkina Faso.", "Operator: poporul Senufo.", "Număr de cuptoare păstrate: 3.", "Minereu folosit: minereu de fier lateritic.", "Statut de protecție: monument cultural din 2005."],
      en: ["Period: 15th century.", "Location: Sindou, Cascades region, Burkina Faso.", "Operator: Senufo people.", "Number of preserved furnaces: 3.", "Ore used: lateritic iron ore.", "Protection status: cultural monument since 2005."],
    },
  }
